scripts.oncreate:
var actor = userprofile.username;
var switches = om.getObjectList('userSwitch', {code:'current'});
if(switches.length > 0 && switches[0].activeUser != null && switches[0].activeUser != '') actor = switches[0].activeUser;
self.requestor = actor;
om.createObject('ticketLog', null, {ticketUid: uid, entry: 'Ticket created by ' + actor, category: 'system', createdBy: actor});

scripts.submit:
var actor = userprofile.username;
var switches = om.getObjectList('userSwitch', {code:'current'});
if(switches.length > 0 && switches[0].activeUser != null && switches[0].activeUser != '') actor = switches[0].activeUser;
if(self.status != 'draft' && self.status != 'clarification') throw('Only draft or clarification tickets can be submitted');
if(self.requestor != actor) throw('Only the requester can submit this ticket');
if(self.assignee == null || self.assignee == '') throw('Choose an assignee before submitting');
self.status = 'submitted';
om.createObject('ticketLog', null, {ticketUid: uid, entry: 'Submitted to ' + self.assignee + ' by ' + actor, category: 'workflow', createdBy: actor});

scripts.start:
var actor = userprofile.username;
var switches = om.getObjectList('userSwitch', {code:'current'});
if(switches.length > 0 && switches[0].activeUser != null && switches[0].activeUser != '') actor = switches[0].activeUser;
if(self.status != 'submitted') throw('Only submitted tickets can be started');
if(self.assignee != actor) throw('Only the assignee can start work on this ticket');
self.status = 'inprogress';
om.createObject('ticketLog', null, {ticketUid: uid, entry: 'Work started by ' + actor, category: 'workflow', createdBy: actor});

scripts.clarify:
var actor = userprofile.username;
var switches = om.getObjectList('userSwitch', {code:'current'});
if(switches.length > 0 && switches[0].activeUser != null && switches[0].activeUser != '') actor = switches[0].activeUser;
if(self.status != 'submitted' && self.status != 'inprogress') throw('Only submitted or in-progress tickets can be returned for clarification');
if(self.assignee != actor) throw('Only the assignee can request clarification');
self.status = 'clarification';
om.createObject('ticketLog', null, {ticketUid: uid, entry: 'Returned to requester for clarification by ' + actor, category: 'workflow', createdBy: actor});

scripts.resubmit:
var actor = userprofile.username;
var switches = om.getObjectList('userSwitch', {code:'current'});
if(switches.length > 0 && switches[0].activeUser != null && switches[0].activeUser != '') actor = switches[0].activeUser;
if(self.status != 'clarification') throw('Only tickets awaiting clarification can be resubmitted');
if(self.requestor != actor) throw('Only the requester can resubmit this ticket');
if(self.assignee == null || self.assignee == '') throw('Choose an assignee before resubmitting');
self.status = 'submitted';
om.createObject('ticketLog', null, {ticketUid: uid, entry: 'Clarification supplied and ticket resubmitted by ' + actor, category: 'workflow', createdBy: actor});

scripts.archive:
