var switches = om.getObjectList('userSwitch', {code:'current'});
if(switches.length > 0 && switches[0].activeUser != null && switches[0].activeUser != '') actor = switches[0].activeUser;
if(self.status != 'inprogress') throw('Only in-progress tickets can be archived');
if(self.assignee != actor) throw('Only the assignee can archive this ticket');
self.status = 'archived';
om.createObject('ticketLog', null, {ticketUid: uid, entry: 'Ticket archived by ' + actor, category: 'workflow', createdBy: actor});
